"""Continuous Subarray Sum — prefix remainders modulo k.

Two prefixes with the same remainder bracket a subarray divisible by k; storing
the first index each remainder appeared enforces the length >= 2 rule.

Time: O(n)   Space: O(min(n, k))
"""
from typing import List


class Solution:
    def checkSubarraySum(self, nums: List[int], k: int) -> bool:
        first_seen = {0: -1}
        running = 0
        for i, value in enumerate(nums):
            running = (running + value) % k
            if running in first_seen:
                if i - first_seen[running] >= 2:
                    return True
            else:
                first_seen[running] = i
        return False
